project-workshop-dashboard.style.css:
* { box-sizing: border-box; }
body { margin: 0; padding: 20px 14px; background: #edf5f2; color: #243447; font: 16px/1.6 system-ui, sans-serif; }
.sheet { max-width: 760px; margin: 0 auto; padding: 20px; border-radius: 12px; background: white; }
h1 { margin: 0 0 .5em; font-size: 1.5rem; line-height: 1.3; }
button, input, select, textarea { font: inherit; }
img, video { max-width: 100%; height: auto; }
a { color: #125a46; }

.dashboard { margin: 0 auto; max-width: 900px; }
.dashboard > * { padding: 12px; border-radius: 8px; background: white; }
.links a { display: block; }
.cards article { padding: 8px; background: #e6f4ee; border-radius: 6px; }
.cards h3 { margin: 0; }

.dashboard, .cards { display: grid; gap: 12px; }
@media (min-width: 700px) {
  .dashboard { grid-template-columns: 160px minmax(0, 1fr); }
  #top { grid-column: 1 / -1; }
  .cards { grid-template-columns: 1fr 1fr; }
}
